name: Coverage Comment

on:
  # The so-called dangerous workflow_run trigger is necessary for letting forks
  # gain workflow-scoped pull-requests: write permission. The only
  # user-controlled content is the content of diff-cover-report.md.
  workflow_run:  # zizmor: ignore[dangerous-triggers]
    workflows: ["Coverage Tests"]
    types:
      - completed

permissions:
  actions: read
  pull-requests: write

jobs:
  comment:
    if: >
      github.event.workflow_run.event == 'pull_request' &&
      github.event.workflow_run.conclusion == 'success' &&
      github.repository == 'django/django'
    name: Post Coverage Comment
    runs-on: ubuntu-latest
    timeout-minutes: 60
    steps:
      - name: Download coverage artifacts
        uses: actions/download-artifact@v8
        with:
          name: coverage-artifacts
          github-token: ${{ secrets.GITHUB_TOKEN }}
          run-id: ${{ github.event.workflow_run.id }}

      - name: Post/update PR comment
        uses: actions/github-script@v9
        with:
          script: |
            const fs = require('fs');
            const reportPath = 'diff-cover-report.md';
            let body = 'No coverage data available.';
            if (fs.existsSync(reportPath)) {
              body = fs.readFileSync(reportPath, 'utf8');
              const divider = '-------------';
              // Start after the second divder, where changed files are listed.
              const start = body.indexOf(divider, 1);
              body = body.substring(start);
            }
            const commentBody = (
              '#### Uncovered lines in changed files\n\n```\n' + body + '```\n' +
              '**Note:** Missing lines are warnings only. Some database-specific lines may not be measured. [More information](https://docs.djangoproject.com/en/dev/internals/contributing/writing-code/unit-tests/#code-coverage-on-pull-requests)'
            );

            const run = context.payload.workflow_run;
            const { data: prs } = await github.rest.pulls.list({
              owner: context.repo.owner,
              repo: context.repo.repo,
              state: "open",
              head: `${run.head_repository.owner.login}:${run.head_branch}`,
            });
            const pr = prs[0];
            if (!pr) {
              core.setFailed(`No PR found for commit ${run.head_sha}.`);
              return;
            }

            const { data: comments } = await github.rest.issues.listComments({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: pr.number,
            });

            for (const c of comments) {
              if ((c.body || '').includes('Uncovered lines in changed files')) {
                await github.rest.issues.deleteComment({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  comment_id: c.id,
                });
              }
            }

            await github.rest.issues.createComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: pr.number,
              body: commentBody,
            });

reusable_workflows..github/workflows/labels.yml:
name: Labels

on:
  pull_request_target:
    types: [ edited, opened, reopened, ready_for_review ]
    branches:
      - main

concurrency:
  # Avoid github.ref, which is always main for the pull_request_target trigger.
  group: ${{ github.workflow }}-${{ github.event.pull_request.number }}
  cancel-in-progress: true

permissions:
  pull-requests: write

jobs:
  no_ticket:
    # Only trigger on the main Django repository
    if: github.repository == 'django/django'
    name: "Flag if no Trac ticket is found in the title"
    runs-on: ubuntu-latest
    timeout-minutes: 60
    steps:
      - name: "Check title and manage labels"
        uses: actions/github-script@v9
        with:
          script: |
            const title = context.payload.pull_request.title;
            const regex = /#[0-9]+[ ,:]?/gm;
            const label = "no ticket";
            const hasMatch = regex.test(title);
            const labels = context.payload.pull_request.labels.map(l => l.name);
            const owner = context.repo.owner;
            const repo = context.repo.repo;
            const pr_number = context.payload.pull_request.number;
            console.log(`=> Pull Request Title: ${title}`);
            console.log(`=> Labels on PR: [${labels}]`);
            if (hasMatch && labels.includes(label)) {
              console.log(`==> Removing label "${label}" from PR #${pr_number}`);
              await github.rest.issues.removeLabel({
                owner,
                repo,
                issue_number: pr_number,
                name: label
              });
            } else if (!hasMatch && !labels.includes(label)) {
              console.log(`==> Adding label "${label}" to PR #${pr_number}`);
              await github.rest.issues.addLabels({
                owner,
                repo,
                issue_number: pr_number,
                labels: [label]
              });
            } else {
              console.log(`No action needed for PR #${pr_number}`);
            }
